using System;using System.Linq;using UnityEditor;using UnityEngine;using RoadGunner;using RoadGunner.Editor;
public static class GreenwoodFinalArt{public static string Main(){if(EditorApplication.isPlaying)throw new InvalidOperationException("Stop Play");var l=RoadGunnerLevelAuthoring.Current;var q=Quaternion.Euler(0,45,0);
 var boundary=l.obstaclesRoot.Find("01 · Rock boundaries and islands");foreach(Transform t in boundary){var p=Quaternion.Inverse(q)*t.position;if(t.name=="Cliff"&&((Mathf.Abs(p.x-40.5f)<.2f&&Mathf.Abs(p.z-47)<.2f)||(Mathf.Abs(p.x-43)<.2f&&Mathf.Abs(p.z-49)<.2f))){var scale=t.localScale;scale.y=.527f;t.localScale=scale;PrefabUtility.RecordPrefabInstancePropertyModifications(t);}}
 foreach(Transform section in l.decorationRoot)if(section.name.StartsWith("Cliff crown"))foreach(Transform t in section){var p=Quaternion.Inverse(q)*t.position;if((Mathf.Abs(p.x-39.7f)<.2f&&Mathf.Abs(p.z-47.5f)<.2f)||(Mathf.Abs(p.x-42.2f)<.2f&&Mathf.Abs(p.z-49.5f)<.2f)){t.position=AstraZone01Builder.World(p.x,p.z,3.162f);t.localScale=Vector3.one*.6f;PrefabUtility.RecordPrefabInstancePropertyModifications(t);}}
 var garden=l.decorationRoot.Find("C · Sanctuary garden");foreach(Transform t in garden.Cast<Transform>().ToArray()){var p=Quaternion.Inverse(q)*t.position;if(t.name=="Boulder"&&p.x>=7.5f&&p.x<=13&&p.z>=-17&&p.z<=1){if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(12,-12))<4.9f){UnityEngine.Object.DestroyImmediate(t.gameObject);continue;}var scale=t.localScale;scale.y=.075f;t.localScale=scale;}}
 Func<string,Material> mat=name=>AssetDatabase.LoadAssetAtPath<Material>(AstraZone01Builder.Root+"/Materials/"+name+".mat");
 foreach(string name in new[]{"Forest Scavenger","West Champion"}){string path=AstraZone01Builder.Root+"/Prefabs/"+name+".prefab";var root=PrefabUtility.LoadPrefabContents(path);foreach(var r in root.GetComponentsInChildren<Renderer>(true)){string n=r.name.ToLowerInvariant();if(name=="West Champion"&&n.Contains("crowbar")){r.enabled=false;continue;}Material m=n.Contains("crowbar")||n.Contains("scrap plate")?mat("Metal"):n.Contains("head wrap")?mat("Red"):n=="head"?mat("Skin"):n.Contains("boot")?mat("Dark"):null;if(m)r.sharedMaterials=r.sharedMaterials.Select(_=>m).ToArray();}PrefabUtility.SaveAsPrefabAsset(root,path);PrefabUtility.UnloadPrefabContents(root);}
 string archPath=AstraZone01Builder.Root+"/Prefabs/Stone Arch.prefab";var arch=PrefabUtility.LoadPrefabContents(archPath);if(!arch.transform.Find("Cyan core")){var core=new GameObject("Cyan core");core.transform.SetParent(arch.transform,false);core.transform.localPosition=Vector3.up*.53f;core.transform.localScale=new Vector3(1.2f,1.8f,1.2f);core.AddComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(AstraZone01Builder.Root+"/Meshes/Faceted stone.asset");core.AddComponent<MeshRenderer>().sharedMaterial=mat("Cyan");core.isStatic=true;}PrefabUtility.SaveAsPrefabAsset(arch,archPath);PrefabUtility.UnloadPrefabContents(arch);
 RoadGunnerLevelAuthoring.Save(l);return "Foreground cliffs reduced; pool cleared; large cyan core, skin, red wraps and metal weapons assigned";}}
